export interface ValidationResult {
  valid: boolean
  errors: string[]
}

export function validateEmail(email: string): ValidationResult {
  const errors: string[] = []
  if (!email) {
    errors.push("Email is required")
  } else {
    if (!email.includes("@")) errors.push("Email must contain @")
    if (!email.includes(".")) errors.push("Email must contain a dot")
    if (email.startsWith("@") || email.endsWith("@")) errors.push("@ must not be at the start or end")
    if (email.length > 254) errors.push("Email too long (max 254 chars)")
  }
  return { valid: errors.length === 0, errors }
}

export function validatePassword(password: string): ValidationResult {
  const errors: string[] = []
  if (!password) {
    errors.push("Password is required")
  } else {
    if (password.length < 8) errors.push("Password must be at least 8 characters")
    if (!/[A-Z]/.test(password)) errors.push("Password must contain an uppercase letter")
    if (!/[0-9]/.test(password)) errors.push("Password must contain a number")
    if (!/[^A-Za-z0-9]/.test(password)) errors.push("Password must contain a special character")
  }
  return { valid: errors.length === 0, errors }
}

