    it("rejects a password shorter than 8 characters with only the length error", () => {
      const result = validatePassword("Pa1!") // 4 chars, has upper + number + special
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual(["Password must be at least 8 characters"])
    })

    it("rejects a password missing an uppercase letter with only that error", () => {
      const result = validatePassword("password1!")
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual([
        "Password must contain an uppercase letter",
      ])
    })

    it("rejects a password missing a number with only that error", () => {
      const result = validatePassword("Password!")
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual(["Password must contain a number"])
    })

    it("rejects a password missing a special character with only that error", () => {
      const result = validatePassword("Password1")
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual([
        "Password must contain a special character",
      ])
    })
  })

  describe("boundary values", () => {
    it("accepts a password of exactly 8 characters (the minimum length)", () => {
      const result = validatePassword("Passw0r!") // 8 chars, upper + number + special
      expect(result.valid).toBe(true)
      expect(result.errors).toEqual([])
    })

    it("rejects a 7-character password that otherwise meets every rule", () => {
      const result = validatePassword("Passw0!")
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual(["Password must be at least 8 characters"])
    })
  })

  describe("error accumulation", () => {
    it("collects every failed rule in order for a weak password", () => {
      const result = validatePassword("a")
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual([
        "Password must be at least 8 characters",
        "Password must contain an uppercase letter",
        "Password must contain a number",
        "Password must contain a special character",
      ])
    })

    it("collects all character-class errors for an all-lowercase password of valid length", () => {
      const result = validatePassword("abcdefgh")
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual([
        "Password must contain an uppercase letter",
        "Password must contain a number",
        "Password must contain a special character",
      ])
    })
  })

  describe("edge cases", () => {
    it("treats a whitespace-only password as missing every character class", () => {
      const result = validatePassword("        ") // 8 spaces: long enough, but no upper/number/special
      expect(result.valid).toBe(false)
      expect(result.errors).toEqual([
        "Password must contain an uppercase letter",
        "Password must contain a number",
        "Password must contain a special character",
      ])
    })
  })
})
